DECLARE m public.master_v2_sessions;q mission_factory_owner.quest_run_sources;users uuid[];
BEGIN
PERFORM mission_factory_owner.c395_source_assert_v1(p_session);
SELECT * INTO STRICT m FROM public.master_v2_sessions WHERE id=p_session FOR SHARE;
SELECT * INTO STRICT q FROM mission_factory_owner.quest_run_sources WHERE session_id=p_session FOR SHARE;
SELECT array_agg(c.user_id ORDER BY c.id) INTO users FROM unnest(q.roster_character_ids) x(id) JOIN public.characters c ON c.id=x.id;
IF q.state IS DISTINCT FROM 'started' OR m.closed_at IS NOT NULL OR m.suspended_at IS NOT NULL OR m.stato NOT IN('in_corso','chiusura')
OR m.master_user IS DISTINCT FROM auth.uid() OR auth.role() IS DISTINCT FROM 'authenticated'
OR ((q.location_id IS DISTINCT FROM '0b85f354-9cdb-47e1-baf9-3d266bb7e06b'::uuid
 OR q.availability_scope IS DISTINCT FROM 'staff' OR q.execution_context IS DISTINCT FROM 'staff_simulation'
 OR combat_consumer_private.staff_test_allowed(q.location_id,array_append(users,auth.uid()),false) IS DISTINCT FROM true)
 AND mission_factory_owner.human_ordinary_source_v1(p_session,true) IS NULL)
THEN RAISE EXCEPTION 'C395_HUMAN_ACTIVE_STAFF_SCOPE_REQUIRED' USING ERRCODE='42501';END IF;
END

DECLARE q mission_factory_owner.quest_run_sources;m public.master_v2_sessions;p mission_factory_owner.c395_prepared_sources;r mission_factory_owner.c395_quest_revisions;
BEGIN
SELECT * INTO STRICT q FROM mission_factory_owner.quest_run_sources WHERE session_id=p_session FOR SHARE;
SELECT * INTO STRICT m FROM public.master_v2_sessions WHERE id=p_session FOR SHARE;
SELECT * INTO STRICT p FROM mission_factory_owner.c395_prepared_sources WHERE session_id=p_session FOR SHARE;
SELECT * INTO STRICT r FROM mission_factory_owner.c395_quest_revisions WHERE id=p.revision_id FOR SHARE;
IF auth.uid() IS NULL OR auth.role() IS DISTINCT FROM 'authenticated' OR m.master_user IS DISTINCT FROM auth.uid()
OR m.owner_kind IS DISTINCT FROM 'human' OR m.mission_id IS NOT NULL OR m.tipo IS DISTINCT FROM 'quest'
OR p.assigned_master IS DISTINCT FROM m.master_user OR r.assigned_master IS DISTINCT FROM m.master_user
OR q.episode_id IS DISTINCT FROM r.episode_id OR q.arc_id IS DISTINCT FROM r.arc_id OR q.source_sha256 IS DISTINCT FROM r.source_sha256
OR p_definition IS DISTINCT FROM q.definition_id OR p_snapshot IS DISTINCT FROM mission_factory_owner.c395_binding_projection_v1(q)
OR p_sha IS DISTINCT FROM mission_internal.fingerprint(p_snapshot) OR q.availability_scope IS DISTINCT FROM 'staff'
OR q.execution_context IS DISTINCT FROM 'staff_simulation' OR q.location_id IS DISTINCT FROM m.location_id
THEN RAISE EXCEPTION 'C395_HUMAN_BINDING_SOURCE_INVALID' USING ERRCODE='42501';END IF;
END

DECLARE v mission_factory_owner.c384_authoring_versions;u uuid:=auth.uid();
a mission_factory_owner.quest_arcs;e mission_factory_owner.quest_episodes;ordinary boolean:=false;
BEGIN
SELECT * INTO e FROM mission_factory_owner.quest_episodes WHERE id=p_episode;
SELECT * INTO a FROM mission_factory_owner.quest_arcs WHERE id=e.arc_id;
ordinary:=a.availability_scope='public' AND a.execution_context='public_real'
 AND mission_public_owner.human_positive_qualification_v1(a.public_release_sha256,true) IS NOT NULL
 AND EXISTS(SELECT 1 FROM public.locations l WHERE l.id=p_location AND l.is_active AND NOT l.is_test AND NOT coalesce(l.is_exam_room,false));
IF u IS NULL OR auth.role() IS DISTINCT FROM 'authenticated' OR p_lineage IS NULL OR p_version IS NULL OR p_episode IS NULL
OR (CASE WHEN a.availability_scope='public' AND a.execution_context='public_real' THEN ordinary IS DISTINCT FROM true ELSE p_location IS DISTINCT FROM '0b85f354-9cdb-47e1-baf9-3d266bb7e06b'::uuid END)
THEN RAISE EXCEPTION 'C395_NORMAL_STAFF_HUMAN_INPUT_REQUIRED' USING ERRCODE='42501';END IF;
PERFORM mission_factory_owner.assert_editor(u);
IF public.master_v2_is_master(u) IS DISTINCT FROM true
OR NOT EXISTS(SELECT 1 FROM mission_factory_owner.c395_control WHERE singleton AND prepare_enabled)
OR NOT EXISTS(SELECT 1 FROM mission_factory_owner.c384_control WHERE singleton AND enabled)
THEN RAISE EXCEPTION 'C395_HUMAN_PREPARE_DISABLED' USING ERRCODE='42501';END IF;
SELECT * INTO STRICT v FROM mission_factory_owner.c384_authoring_versions WHERE lineage_id=p_lineage AND version=p_version FOR SHARE;
IF v.author_user IS DISTINCT FROM u OR v.document#>>'{variants,human,state}' IS DISTINCT FROM 'complete'
THEN RAISE EXCEPTION 'C395_HUMAN_VERSION_AUTHORITY_REQUIRED' USING ERRCODE='42501';END IF;
PERFORM mission_factory_owner.c384_validate_dual_draft_v3(v.document);
PERFORM mission_factory_owner.quest_operator_assert_v3(p_episode);
END

DECLARE v mission_factory_owner.c384_authoring_versions;e mission_factory_owner.quest_episodes;a mission_factory_owner.quest_arcs;
h mission_factory_owner.c395_quest_revisions;ep jsonb;arenas jsonb;rid uuid;u uuid:=auth.uid();
BEGIN
IF u IS NULL OR auth.role() IS DISTINCT FROM 'authenticated' OR p_request IS NULL
THEN RAISE EXCEPTION 'C395_NORMAL_AUTH_REVISION_REQUIRED' USING ERRCODE='42501';END IF;
PERFORM mission_factory_owner.assert_editor(u);
PERFORM pg_advisory_xact_lock(hashtextextended('c395-revision:'||p_episode::text,395));
SELECT * INTO h FROM mission_factory_owner.c395_quest_revisions WHERE episode_id=p_episode;
IF FOUND THEN
IF (h.lineage_id,h.authoring_version,h.arc_id,h.assigned_master,h.request_key) IS DISTINCT FROM (p_lineage,p_version,p_arc,u,p_request)
THEN RAISE EXCEPTION 'C395_REVISION_REQUEST_CONFLICT' USING ERRCODE='22023';END IF;RETURN h.id;
END IF;
SELECT * INTO STRICT v FROM mission_factory_owner.c384_authoring_versions WHERE lineage_id=p_lineage AND version=p_version FOR SHARE;
SELECT * INTO STRICT e FROM mission_factory_owner.quest_episodes WHERE id=p_episode AND arc_id=p_arc FOR SHARE;
SELECT * INTO STRICT a FROM mission_factory_owner.quest_arcs WHERE id=p_arc FOR SHARE;
SELECT value INTO STRICT ep FROM jsonb_array_elements(v.document#>'{quest,episodes}') x WHERE value->>'episode_key'=e.episode_key;
IF v.author_user IS DISTINCT FROM u OR a.created_by IS DISTINCT FROM u OR v.document#>>'{variants,human,state}' IS DISTINCT FROM 'complete'
OR ep IS DISTINCT FROM e.source_document OR e.source_sha256 IS DISTINCT FROM mission_factory_owner.sha(ep)
OR ((a.availability_scope IS DISTINCT FROM 'staff' OR a.execution_context IS DISTINCT FROM 'staff_simulation') AND NOT(a.availability_scope='public' AND a.source_document->>'content_kind'='quest_human' AND mission_factory_owner.human_ordinary_arc_scope_v1(a.id,true)))
OR e.state IS DISTINCT FROM 'source_only' OR v.document#>>'{quest,quest_kind}' IS DISTINCT FROM a.quest_kind
OR NOT EXISTS(SELECT 1 FROM mission_factory_owner.c395_control WHERE singleton AND prepare_enabled)
THEN RAISE EXCEPTION 'C395_IMMUTABLE_COMMON_SOURCE_REQUIRED' USING ERRCODE='42501';END IF;
PERFORM mission_factory_owner.c384_validate_dual_draft_v3(v.document);
IF mission_factory_owner.quest_compile_check_v1(e.id) IS DISTINCT FROM '[]'::jsonb
THEN RAISE EXCEPTION 'C395_NATIVE_COMPILE_QUALIFICATION_REQUIRED' USING ERRCODE='42501';END IF;
-- Arena refs are authored/versioned; no UUID or qualification is invented.
SELECT coalesce(jsonb_agg(jsonb_build_object('step_key',x.value->>'step_key',
'template_key',x.value#>>'{arena_ref,template_key}','template_version',x.value#>'{arena_ref,template_version}',
'zone_key',x.value#>>'{arena_ref,zone_key}',
'catalog_sha256',combat_panel_private.universal_arena_hash(x.value#>>'{arena_ref,template_key}',(x.value#>>'{arena_ref,template_version}')::integer)) ORDER BY x.value->>'step_key'),'[]'::jsonb)
INTO arenas FROM jsonb_array_elements(ep->'maps') x WHERE jsonb_typeof(x.value->'arena_ref')='object';
rid:=extensions.uuid_generate_v5(p_request,'mission-factory:human-quest-revision/1');
INSERT INTO mission_factory_owner.c395_quest_revisions(id,lineage_id,authoring_version,arc_id,episode_id,assigned_master,source_sha256,document,document_sha256,arena_sources,request_key)
VALUES(rid,p_lineage,p_version,p_arc,p_episode,u,e.source_sha256,v.document#>'{variants,human,document}',
mission_factory_owner.sha(v.document#>'{variants,human,document}'),arenas,p_request);
RETURN rid;
END

declare q mission_factory_owner.quest_run_sources%rowtype;
m public.master_v2_sessions%rowtype;
e mission_factory_owner.quest_episodes%rowtype;
a mission_factory_owner.quest_arcs%rowtype;
pub mission_factory_owner.publications%rowtype;
p public.mission_plans%rowtype;
v public.mission_plan_versions%rowtype;
d mission_generic_owner.definitions%rowtype;
b mission_generic_owner.run_bindings%rowtype;
loc public.locations%rowtype;
users uuid[];
begin

PERFORM mission_factory_owner.c384_human_identity_v1(p_session);
PERFORM mission_factory_owner.c395_revision_assert_v1(p_session);
select * into strict q from mission_factory_owner.quest_run_sources where session_id=p_session for share;
select * into strict m from public.master_v2_sessions where id=p_session for share;
select * into strict e from mission_factory_owner.quest_episodes where id=q.episode_id for share;
select * into strict a from mission_factory_owner.quest_arcs where id=q.arc_id for share;
select * into strict pub from mission_factory_owner.publications
where request_key=a.publication_request for share;
select * into strict p from public.mission_plans where id=q.plan_id for share;
select * into strict v from public.mission_plan_versions where id=q.plan_version_id for share;
select * into strict d from mission_generic_owner.definitions where id=q.definition_id for share;
select * into strict b from mission_generic_owner.run_bindings where master_session_id=p_session for share;
select * into strict loc from public.locations where id=q.location_id for share;
select array_agg(c.user_id order by x.ord) into users
from unnest(q.roster_character_ids) with ordinality x(id,ord)
join public.characters c on c.id=x.id and c.user_id is not null;
if m.tipo<>'quest' or m.owner_kind<>'human' or m.master_user IS DISTINCT FROM auth.uid()
or m.mission_id is not null or m.quest_kind is distinct from a.quest_kind
or m.location_id<>q.location_id
or (q.state not in ('terminal','cancelled') and m.stato in ('chiusa','annullata'))
or e.arc_id<>q.arc_id or e.source_sha256<>q.source_sha256 or e.ordinal<>q.episode_ordinal or e.member_character_ids is distinct from q.roster_character_ids
or (q.episode_ordinal>1 and not exists(select 1 from mission_factory_owner.quest_terminal_receipts tr
join mission_factory_owner.quest_episodes pe on pe.id=tr.episode_id
join mission_factory_owner.quest_run_sources pq on pq.episode_id=pe.id and pq.terminal_receipt_id=tr.id
where tr.id=q.previous_episode_terminal_receipt_id and pe.arc_id=q.arc_id and pe.ordinal=q.episode_ordinal-1
and pq.state='terminal' and tr.continuity_private_sha256=q.continuity_sha256
and tr.continuity_private_sha256=mission_factory_owner.sha(tr.continuity_private)))
or (q.state='prepared' and e.state<>'source_only')
or (q.state in('opening_pending','uncertain','started')
and e.state not in('source_only','open','in_progress'))
or a.state not in ('staff_source','public_source','in_progress','completed','failed')
or pub.content_kind<>'quest_human' or not mission_factory_owner.quest_public_open_v3(a.id)
or pub.quest_arc_id<>q.arc_id
or pub.release_revision_sha256 is distinct from q.staff_release_sha256
or p.source_kind<>'quest' or p.quest_episode_id<>q.episode_id
or p.quest_source_sha256<>q.source_sha256
or p.mission_id is not null or v.plan_id<>q.plan_id or v.stato<>'approvata'
or v.plan_sha256<>q.plan_sha256
or d.plan_version_id<>q.plan_version_id or d.plan_sha256<>q.plan_sha256
or d.definition_sha256<>q.definition_sha256
or d.definition_sha256<>mission_internal.fingerprint(d.definition)
or d.definition->>'schema_version'<>'mission-factory-quest-definition/1'
or d.definition->>'quest_episode_id' is distinct from q.episode_id::text
or d.definition->>'source_sha256' is distinct from q.source_sha256
or b.definition_id is distinct from q.definition_id
or b.snapshot is distinct from mission_factory_owner.c395_binding_projection_v1(q)
or b.snapshot_sha256 is distinct from mission_internal.fingerprint(b.snapshot)
or q.roster_snapshot_sha256<>mission_factory_owner.sha(to_jsonb(q.roster_character_ids))
or cardinality(users)<>cardinality(q.roster_character_ids)
or (select count(distinct x) from unnest(q.roster_character_ids)x)<>cardinality(q.roster_character_ids)
or not loc.is_active or loc.is_test is distinct from mission_factory_owner.quest_is_simulation_v4(q.arc_id) or (not mission_factory_owner.quest_is_simulation_v4(q.arc_id) and loc.is_exam_room)
or (mission_factory_owner.quest_is_simulation_v4(q.arc_id) and not combat_consumer_private.staff_test_allowed(q.location_id,users,false))
or q.execution_context is distinct from a.execution_context or q.execution_qualification_sha256 is distinct from a.execution_qualification_sha256
or (a.execution_context='staff_simulation' and a.availability_scope='public' and (q.location_id<>'0b85f354-9cdb-47e1-baf9-3d266bb7e06b'::uuid or exists(select 1 from public.characters c where c.id=any(q.roster_character_ids) and not(c.user_id=any(a.execution_auth_ids)))))
or q.availability_scope is distinct from a.availability_scope or q.public_release_sha256 is distinct from a.public_release_sha256
then raise exception 'MF_QUEST_RUN_SOURCE_STALE' using errcode='42501'; end if;
if q.availability_scope='public' then perform mission_factory_owner.quest_execution_assert_v4(a.id,q.state not in('terminal','cancelled'));end if;
return jsonb_build_object('schema_version','quest-run-source/1',
'session_id',q.session_id,'arc_id',q.arc_id,'episode_id',q.episode_id,
'source_sha256',q.source_sha256,'plan_version_id',q.plan_version_id,
'plan_sha256',q.plan_sha256,'roster_snapshot_sha256',q.roster_snapshot_sha256,
'staff_release_sha256',q.staff_release_sha256,'location_id',q.location_id,
'state',q.state,'control_version',q.control_version);
end

